<?php require_once __DIR__.'/_header.php'; $pdo=Database::pdo(); if(isset($_GET['read'])){$pdo->prepare('UPDATE messages SET is_read=1 WHERE id=?')->execute([(int)$_GET['read']]);header('Location:messages.php');exit;} $rows=$pdo->query('SELECT * FROM messages ORDER BY id DESC')->fetchAll();?><h1>Messages</h1><div class="table"><table><tr><th>Date</th><th>Name</th><th>Email</th><th>Message</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=nl2br(e($r['message']))?></td><td><?=$r['is_read']?'Read':'<a href="?read='.$r['id'].'">Mark read</a>'?></td></tr><?php endforeach;?></table></div><?php require_once __DIR__.'/_footer.php';?>
